// HasRun applies the HasEdge predicate on the "run" edge.
func HasRun() predicate.BenchmarkScoreSnapshot {
	return predicate.BenchmarkScoreSnapshot(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, RunTable, RunColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRunWith applies the HasEdge predicate on the "run" edge with a given conditions (other predicates).
func HasRunWith(preds ...predicate.BenchmarkRun) predicate.BenchmarkScoreSnapshot {
	return predicate.BenchmarkScoreSnapshot(func(s *sql.Selector) {
		step := newRunStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasRunTarget applies the HasEdge predicate on the "run_target" edge.
func HasRunTarget() predicate.BenchmarkScoreSnapshot {
	return predicate.BenchmarkScoreSnapshot(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, RunTargetTable, RunTargetColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRunTargetWith applies the HasEdge predicate on the "run_target" edge with a given conditions (other predicates).
func HasRunTargetWith(preds ...predicate.BenchmarkRunTarget) predicate.BenchmarkScoreSnapshot {
	return predicate.BenchmarkScoreSnapshot(func(s *sql.Selector) {
		step := newRunTargetStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BenchmarkScoreSnapshot) predicate.BenchmarkScoreSnapshot {
	return predicate.BenchmarkScoreSnapshot(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BenchmarkScoreSnapshot) predicate.BenchmarkScoreSnapshot {
	return predicate.BenchmarkScoreSnapshot(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BenchmarkScoreSnapshot) predicate.BenchmarkScoreSnapshot {
	return predicate.BenchmarkScoreSnapshot(sql.NotPredicates(p))
}
